--- a/src/support/impersonate.ts
+++ b/src/support/impersonate.ts
@@ -0,0 +1,18 @@
+export function impersonate(sessionStore, supportUserId, targetAccountId) {
+  // Support engineers can already read account data; this mints a session
+  // token scoped to the target account so the UI renders as they'd see it.
+  const grant = sessionStore.mintSessionToken(targetAccountId, { grantedBy: supportUserId, scope: 'read' });
+  return grant;
+}
